function parseTextoIA(raw) {
  const t = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  if (!t) return { ok: false, tipo_falha: 'formato', erro: 'resposta vazia', raw };
